/* Feature-specific decisions, interpretation checks and image captions; no new capability claims. */
const rows={
 "rain-spatial":["유역 평균 강우만으로 놓칠 수 있는 강우 집중 위치를 살펴봅니다.","관측소·레이더·격자 자료의 시간 간격, 단위와 계산 영역이 일치하는지 확인합니다.","관측자료가 계산격자의 강우 입력으로 이어지는 위치를 보세요. 색상은 강우 공간화의 개념이며 실제 강우량이 아닙니다.","Identify rainfall concentrations that a basin-average input can hide.","Check forcing intervals, units and spatial coverage against the model domain.","Follow the transfer from observations to grid-cell rainfall. Colors illustrate spatial allocation, not measured rainfall.",["rain-methods","rain-summary"]],
 "rain-methods":["같은 관측자료에서도 배분 방법에 따라 달라지는 강우 분포를 비교합니다.","동일 관측기간과 관측소 구성을 사용해 배분 결과를 비교하고 입력자료 점검 결과를 확인합니다.","공통 그림은 관측소에서 격자로 자료가 전달되는 관계를 설명합니다. 두 방법의 가중치나 우열을 비교한 결과는 아닙니다.","Compare the rainfall patterns produced by different mappings of the same observations.","Compare mapping results using the same stations and period, and review the input-quality checks.","This shared image shows station-to-grid mapping, not the weights or relative performance of the two methods.",["rain-spatial","rain-qc"]],
 "rain-qc":["격자 강우의 차이가 고도보정 때문인지 원자료의 품질 문제인지 구분합니다.","고도보정 전제와 원자료의 결측·품질 문제를 확인합니다. 점검을 통과한 자료도 관측 자체의 불확실성은 남습니다.","공간 배분과 자료 점검은 서로 다른 단계입니다. 참고 그림에서 입력자료가 격자로 연결되는 흐름을 보세요.","Distinguish elevation-adjustment effects from problems in the source observations.","Review elevation-adjustment assumptions and missing or questionable source data; passing quality checks does not remove observational uncertainty.","Spatial mapping and input checking are different steps. Follow the connection from input data to model cells.",["rain-methods","input-precheck"]],
 "rain-summary":["해석하려는 홍수·갈수 기간에 결측이나 예측자료가 포함됐는지 판단합니다.","결측 시간수가 0인지, 예측자료가 어느 기간에 포함되는지 확인합니다. 이 집계는 결측 강우를 채워주지 않습니다.","세 유형의 기간을 나누어 집계하는 관계를 보세요. 시간수나 비율은 실제 실행 결과요약에서 확인합니다.","Determine whether the event or low-flow period includes missing or forecast inputs.","Check missing intervals and the forecast portion of the record. These counts do not fill missing rainfall.","Read the three interval categories; obtain actual durations or proportions from the run report.",["run-report","rain-spatial"]],
 "input-precheck":["모의를 시작하기 전에 어떤 입력을 고쳐야 하는지 정합니다.","점검 대상과 오류·경고를 구분하고 수정 후 재확인합니다. 실행 준비 점검과 모의 결과 검증은 별도입니다.","원자료 → 정합성 검사 → 점검 결과의 순서를 보세요. 실제 입력 작성 화면은 아닙니다.","Identify which inputs need correction before starting a simulation.","Distinguish errors from warnings, review check coverage and rerun checks after corrections; result validation is a separate step.","Follow source data, consistency checks and check results. This is not an input-editor screenshot.",["inputstudio","output-integrity"]],
 "ga":["같은 강우에서 토양 상태에 따라 지표유출 기여가 달라지는 이유를 읽습니다.","토양 특성과 초기 수분상태를 함께 살펴봅니다. 침투량과 하류 도달 유량은 서로 다른 계산 단계의 양입니다.","지표의 강우, 토양으로 내려가는 침투, 습윤전선의 이동을 구분해 보세요.","Understand why soil conditions change the surface-runoff contribution under the same rainfall.","Review soil properties and initial moisture; infiltration and downstream discharge belong to different calculation stages.","Distinguish rainfall at the surface, downward infiltration and wetting-front movement.",["runoff","et"]],
 "runoff":["강우 뒤 빠른 유출 반응과 토양층을 통한 유출 기여를 구분합니다.","토양 저장 변화와 유출 전달을 함께 해석합니다. 격자에서 생성된 유출을 하류 지점 유량과 바로 동일시하지 않습니다.","지표와 토양층의 유출 화살표가 하천 쪽으로 모이는 경로를 보세요.","Separate rapid surface response from runoff contributed through soil layers.","Interpret storage changes together with routing; runoff generated in a cell is not the same as discharge at a downstream gauge.","Follow the surface and soil-layer pathways toward the channel.",["ga","kw-hill"]],
 "continuous":["선행 강우와 건조기간이 다음 강우사상의 유출에 미치는 영향을 살펴봅니다.","연속 입력기간과 초기상태를 확인하고, 계절별 물수지와 감수부를 함께 검토합니다.","비가 오는 시기와 마른 시기 사이에도 토양·저장상태가 이어지는 점을 보세요.","Examine how preceding rain and dry periods affect the next event response.","Check continuous forcing and initial states, then review seasonal balance and recession behavior together.","Notice how storage carries between rainy and dry periods.",["warmup","wb"]],
 "et":["건조기간에 줄어든 토양수분이 다음 강우의 유출 반응을 바꾸는지 살펴봅니다.","기상 입력과 토양·식생 조건을 함께 확인합니다. 증발산 수요와 토양에 저장된 물의 관계를 살펴봅니다.","토양에 저장된 물이 식생과 지표를 거쳐 대기로 이동하는 부분을 보세요.","Examine whether dry-period soil-water depletion changes the response to later rainfall.","Review meteorological, soil and vegetation conditions, including the relationship between evaporative demand and stored water.","Follow stored soil water returning to the atmosphere through vegetation and the surface.",["continuous","ga"]],
 "snow":["강수 시점과 유출 증가 시점이 어긋나는 원인을 적설과 융설 과정에서 찾습니다.","강수·기온·풍속과 표고·경사·D8 흐름방향을 확인합니다. 방향·시간대 보정은 경험적 융설계수에 반영되며 직접적인 일사 계산이나 적설 이동 해석과 구분합니다.","강우·강설 구분, 융설계수 보정, 적설 저장량과 융설수의 연결을 보세요. 지형 조건은 융설계수에 반영됩니다.","Investigate whether snow accumulation and melt explain a delay between precipitation and runoff.","Review precipitation, temperature, wind, elevation, slope and D8 direction. Direction/time adjustment is empirical, not a direct radiation or snow-transport calculation.","Follow rain/snow partitioning, melt-factor adjustment, snow storage and meltwater. Terrain conditions modify the melt factor.",["continuous","runoff"]],
 "warmup":["초기조건의 영향이 큰 모의 초반 결과를 그대로 해석해도 되는지 판단합니다.","반복이 끝났다는 사실뿐 아니라 목표유량 오차와 상태 변화가 충분히 안정되는지 검토합니다.","초기상태 조정 → 목표지점 평가 → 반복 조정의 연결을 보세요. 저장 상태를 단순히 복원하는 과정과 다릅니다.","Assess whether early results remain strongly influenced by the initial conditions.","Inspect remaining target-flow error and state changes, rather than treating termination as proof of stabilization.","Follow adjustment, target-site review and iteration; this is different from simply restoring a checkpoint.",["hotstart","continuous"]],
 "hotstart":["계산을 나눠 수행할 때 이전 모의와 이어지는 시작 상태를 준비합니다.","저장 상태 파일(체크포인트)의 격자·상태·시간과 필요한 추가 상태의 포함 여부를 확인합니다. 모든 수리 확장이 동일하게 재시작된다고 가정하지 않습니다.","저장된 상태가 다음 계산의 시작점으로 전달되는 연결을 보세요.","Prepare a continuation state when a simulation is carried out in stages.","Check grid, state, time and coverage of required additional states; do not assume identical restart support for every hydraulic extension.","Follow the saved state becoming the starting point for the next computation.",["warmup","output-integrity"]],
 "dlayer":["강우가 끝난 뒤에도 이어지는 감수부와 저유량의 지속성을 살펴봅니다.","관측 감수곡선과 저유량을 비교합니다. 이 저장층 표현은 완전한 지하수유동 해석과 다릅니다.","D층 저장에서 상부 토양층으로 돌아가는 지연 복귀와 별도 선택 조건의 심부 손실을 구분해 보세요.","Examine the persistence of recession flow and low flows after rainfall ends.","Compare recession curves and low flows with observations. This storage representation is not a full groundwater-flow solver.","Distinguish delayed return from D-layer storage to an upper soil layer and the separately enabled loss term.",["river-infil","continuous"]],
 "slope-separate":["흐름 전달의 차이를 검토할 때 사면경사와 하도경사 중 어떤 조건을 볼지 구분합니다.","사면경사와 하도경사의 산정 기준·방향·단위를 각각 확인합니다. 하나의 경사를 모든 경로에 일괄 적용하지 않도록 검토합니다.","사면에서 하도로 이어지는 서로 다른 흐름 경로를 보세요. 경사값을 비교한 정량 도표는 아닙니다.","Identify whether hillslope or channel slope is relevant to a routing difference.","Review the derivation, direction and units of each slope, and check that the intended slope is assigned to each pathway.","Identify the hillslope and channel pathways; the image is not a numerical comparison of slopes.",["kw-hill","kw-river"]],
 "kw-hill":["격자에서 발생한 유출이 하천에 도달하기 전 전달되는 과정을 살펴봅니다.","사면 연결과 경사·조도 등 전달 조건을 확인합니다. 하천 수위에 의한 복잡한 배수위 해석과 적용 범위를 구분합니다.","사면에서 하천으로 물이 모이는 구간에 주목하세요. 공통 그림 중 사면 전달 부분에 해당합니다.","Trace how generated cell runoff travels before entering the river.","Check hillslope connectivity and routing conditions, and distinguish its scope from complex backwater hydraulics.","Focus on the hillslope-to-channel part of the shared routing illustration.",["runoff","kw-river"]],
 "kw-river":["상류·측방에서 모인 물이 하류 유량의 시간 변화로 이어지는 과정을 살펴봅니다.","하도 길이·폭·경사·조도와 연결을 확인합니다. 동역학파에 의한 수위·유량 해석과 동일한 기능으로 보지 않습니다.","하천을 따라 하류로 향하는 경로를 보세요. 사면에서 발생하는 유출과 하도 전달을 구분합니다.","Examine how upstream and lateral contributions form the downstream discharge time series.","Check channel geometry, slope, roughness and connectivity; distinguish this from dynamic-wave water-level and discharge analysis.","Focus on the downstream channel pathway, separate from hillslope runoff generation.",["kw-hill","dwnet"]],
 "river-infil":["하천에서 줄어든 물이 심부 저장 증가와 어떻게 연결되는지 확인합니다.","침투가능량과 심부 저장여유의 제한을 함께 확인하고, 이동량이 두 영역의 물수지에 일관되게 반영되는지 살펴봅니다.","하천 바닥에서 심부저장으로 향하는 화살표를 보세요. 그림의 화살표 크기는 실제 침투량을 뜻하지 않습니다.","Check how water transferred out of the river contributes to deeper storage.","Review infiltration capacity, available deep storage and consistent transfer accounting between the domains.","Follow the riverbed-to-storage arrow; its size does not represent an actual flux.",["dlayer","wb"]],
 "channelbed":["수리해석에 사용할 지형이 수중 저수로 형상을 충분히 담고 있는지 검토합니다.","보완에 사용한 중심선·단면 등 자료와 높이 기준을 확인합니다. 보완 지형은 측량 원자료와 구분해 검토합니다.","지형 표면과 추가로 표현해야 하는 하상·저수로 형상의 차이를 보세요.","Assess whether hydraulic terrain adequately represents the submerged low-flow channel.","Review supporting centerlines or cross sections and vertical references; distinguish supplemented terrain from original survey data.","Compare the terrain surface with the riverbed or low-flow geometry that requires supplementation.",["dwnet","local-inertia"]],
 "wb":["들어온 물이 유출·증발산·저장 변화로 어떻게 배분됐는지 확인하고, 계산 결과의 일관성과 차이의 원인을 살펴봅니다.","같은 기간과 영역, 같은 단위로 각 항을 집계합니다. 작은 폐합오차만으로 관측유량 재현성이 입증되지는 않습니다.","유역 경계를 넘는 유입·유출과 내부 저장량 변화를 구분해 보세요.","Understand how incoming water is partitioned into outflow, evapotranspiration and storage change, and use that accounting to assess consistency and investigate differences.","Use the same domain, period and units for all terms; a small residual does not establish agreement with observed discharge.","Distinguish boundary fluxes from changes in storage inside the watershed.",["wb-1d2d","optimization"]],
 "wb-1d2d":["하천에서 빠진 교환량이 범람원에 빠짐없이 반영됐는지 확인합니다.","교환체적의 단위·집계 시간간격을 맞추고 두 영역의 저장 변화와 대응하는지 확인합니다.","하천–범람원 경계의 양방향 화살표를 보세요. 물수지 판정 결과 자체를 그린 그림은 아닙니다.","Check whether the volume leaving the river is fully accounted for in the floodplain.","Match exchanged-volume units and accounting intervals, then check correspondence with storage changes in both domains.","Focus on the bidirectional boundary arrows, not on an implied water-balance pass result.",["coupling","wb"]],
 "run-report":["두 실행의 결과가 다를 때 먼저 비교할 조건과 경고를 찾습니다.","실행방식과 초기상태가 의도한 조건인지 먼저 확인한 뒤 경고와 물수지를 살펴봅니다.","실행 조건을 기록하는 단계에 주목하세요. 출력 파일의 정상 여부를 점검하는 단계와 역할이 다릅니다.","Find the conditions and warnings to compare first when two runs differ.","Confirm run mode and initial states first, then review warnings and water balance.","Focus on recording run context, distinct from checking output-file integrity.",["rain-summary","output-integrity"]],
 "subbasin-report":["전체 유역 결과에 가려진 지역별 기여 차이를 찾아 후속 검토 대상을 좁힙니다.","소유역 경계와 평가 지점의 대응, 집계기간·단위를 확인합니다. 보고 단위 구분과 매개변수 보정은 별도입니다.","소유역 경계와 관측지점이 어떻게 대응하는지 보세요. 그림의 영역은 예시입니다.","Locate regional contributions hidden in basin-wide results and narrow the next review.","Check boundaries, gauge correspondence, periods and units; reporting units do not perform parameter calibration.","Read the relationship between subbasin boundaries and evaluation points in the illustrative domain.",["subcal","wb"]],
 "optimization":["목표지점의 첨두·총량·감수부 중 어떤 특성이 개선되거나 악화됐는지 판단합니다.","관측 품질과 평가기간을 확인하고 첨두·시점·총량·감수부를 함께 검토합니다. 보정기간 외 자료로도 재평가합니다.","관측자료와 여러 매개변수 조합이 같은 평가 단계로 모이는 흐름을 보세요. 최적화 성능을 입증한 수치 예시는 아닙니다.","Judge which target-site characteristics improve or deteriorate: peak, volume or recession.","Review observation quality and evaluation periods, inspect peaks, timing, volume and recession, and reassess outside the calibration period.","Follow observations and candidate parameters into a common evaluation; no optimization performance is demonstrated by the schematic.",["subcal","wb"]],
 "subcal":["어느 소유역의 문제를 먼저 보정 검토에 연결할지 우선순위를 정합니다.","소유역 보고 결과와 목표지점의 관계를 확인합니다. 모든 소유역의 매개변수를 자동으로 찾아주는 기능으로 해석하지 않습니다.","소유역과 지점의 대응을 먼저 보세요. 보정 계산은 연결된 목표지점 보정 기능에서 별도로 설명합니다.","Prioritize which subbasin findings to bring into calibration review.","Check how subbasin findings relate to the target site; do not assume automatic parameter targeting for every subbasin.","Start with subbasin-to-gauge correspondence; the linked calibration feature explains parameter-case evaluation.",["subbasin-report","optimization"]],
 "output-integrity":["생성된 결과 파일을 결과 분석에 사용해도 되는지 실행 오류와 출력 요건으로 판단합니다.","오류상태와 필요한 결과항목을 확인합니다. 파일이 정상이라고 수문·수리 결과까지 타당한 것은 아닙니다.","결과 생성 이후 출력 요건을 점검하고 결과 분석으로 전달하는 순서를 보세요.","Decide whether outputs are ready for postprocessing by reviewing errors and required content.","Review error states and required outputs; valid files do not by themselves establish physically valid results.","Follow file creation, output checks and handover to postprocessing.",["netcdf","run-report"]],
 "dwnet":["하천 구간 간 수위·유량의 상호 영향을 검토할 해석 경로를 살펴봅니다.","하천망·단면·경계조건과 관측 수위·유량을 함께 검토합니다. 적용 유역의 신뢰성 평가는 별도로 필요합니다.","지류와 본류, 분기 및 횡단면의 연결을 보세요. 화살표는 하천망의 개념적 방향입니다.","Explore a hydraulic path for examining water-level and discharge interactions between reaches.","Review network geometry, cross sections, boundary conditions and observed levels or flows for the basin of interest.","Identify tributaries, the main river, branches and cross sections; arrows indicate conceptual connectivity.",["junction","kw-river"]],
 "junction":["합류·분기 지점에서 각 구간의 유량과 수위가 어떻게 연결되는지 살펴봅니다.","연결 방향과 연속조건을 확인하고 합류·분기 전후 구간을 함께 검토합니다.","공통 하천망 그림에서 여러 구간이 만나는 점과 갈라지는 점에 주목하세요.","Examine how reach discharges and water levels connect at a confluence or branch.","Review connection direction and continuity together with the adjacent reaches.","Focus on the meeting and splitting points in the shared river-network illustration.",["dwnet","structures"]],
 "structures":["구조물 전후의 흐름 차이가 어떤 수위·제원 조건에서 생기는지 살펴봅니다.","구조물 형식·제원·수위 조건과 적용하는 유량 관계를 확인합니다. 실제 구조물의 운영자료와 함께 검토해야 합니다.","월류턱을 넘는 흐름과 수문 아래로 흐르는 물의 차이를 보세요. 실제 설계 제원을 나타낸 그림은 아닙니다.","Examine which water levels and dimensions govern flow across a structure.","Check structure type, dimensions, water levels and the applicable discharge relationship against the actual structure data.","Compare overflow across a crest with flow beneath a gate; dimensions are illustrative.",["dwnet","dam-operation"]],
 "dam-operation":["주어진 운영규칙에서 저류와 방류가 어떤 제약을 받는지 읽습니다.","대상 댐의 운영규칙·방류제약과 초기 저수상태를 별도로 확보하고 확인합니다. 공개 홈페이지는 실제 운영규칙을 제공하지 않습니다.","저수지의 유입·방류와 하류 연결을 보세요. 운영규칙이나 권장 방류량을 제시한 그림은 아닙니다.","Read how specified operating rules constrain storage and releases.","Obtain and review the applicable rules, release constraints and initial storage; this website does not supply actual operating rules.","Identify reservoir inflow, release and downstream connections, not recommended release values.",["dam-forecast","dam-scenario"]],
 "dam-forecast":["예측 유입이 달라질 때 사전방류 대안과 하류 영향이 어떻게 달라지는지 비교합니다.","예측의 불확실성, 저수지 상태와 하류 제약을 함께 확인합니다. 모의 대안은 실제 운영 승인과 구분합니다.","예측 유입, 저수지와 하류 평가구간을 함께 보세요. 방류 대안 간 차이를 검토하는 개념입니다.","Compare how release alternatives and downstream effects change with forecast inflow.","Review forecast uncertainty, reservoir states and downstream constraints; scenario analysis is separate from operational authorization.","Read forecast inflows, reservoirs and downstream assessment reaches together.",["dam-operation","dam-scenario"]],
 "dam-scenario":["같은 평가 조건에서 댐군 운영 대안의 장단점을 목적지표별로 비교합니다.","유입·평가기간·목적지표를 맞춘 뒤 대안별 개선과 악화를 함께 비교합니다.","개별 저수지보다 저수지망과 공통 하류 평가구간에 주목하세요.","Compare trade-offs between reservoir-network alternatives under common evaluation conditions.","Align inflows, evaluation periods and metrics, then compare both improvements and trade-offs.","Focus on the reservoir network and common downstream assessment reach.",["dam-forecast","dam-operation"]],
 "coupling":["월류 이후 범람원에서 하천으로 돌아오는 물까지 해석해야 하는지 검토합니다.","교환 경계·수위·시간간격과 누적 교환량을 두 영역의 저장 변화와 함께 비교합니다.","하천에서 범람원으로 나가는 경로와 복귀 경로를 구분해 보세요.","Consider whether return flow from the floodplain to the river needs to be represented.","Compare interface geometry, stages, time steps and accumulated exchange with storage changes in both domains.","Identify outward and returning flow paths across the river–floodplain boundary.",["wb-1d2d","local-inertia"]],
 "local-inertia":["범람 확산의 공간·시간 변화와 계산비용을 함께 검토합니다.","지형·격자·경계조건과 계산 설정을 확인하고 대상 흐름에 대한 적용성을 검토합니다.","지형 위의 물과 계산격자를 보세요. 공간 구성 개념이며 Local Inertia 방정식이나 실제 침수예측을 보여주는 그림은 아닙니다.","Review flood spreading through space and time together with computational cost.","Review terrain, grid, boundary conditions and numerical settings for the flow regime of interest.","Read the terrain, water and computational cells; the image does not show equations or an actual flood prediction.",["fullswe","multires"]],
 "fullswe":["관심구간의 수면·유속 변화를 분석할 해석 경로를 선택하는 데 참고합니다.","기본 Local Inertia 경로와 목적·설정·검증 범위를 구분합니다. 더 복잡한 해석이 모든 조건에서 더 정확하다는 뜻은 아닙니다.","공통 그림은 2D 해석 공간만 설명합니다. Full SWE와 Local Inertia의 수치기법 차이를 나타내지는 않습니다.","Inform the choice of a solver for water-surface and velocity changes in a focus area.","Distinguish its purpose, settings and validation scope from Local Inertia; greater complexity does not guarantee greater accuracy.","The shared picture shows only the 2D spatial setting, not differences between Full SWE and Local Inertia.",["local-inertia","multires"]],
 "multires":["어디에 원지형 해상도를 유지해야 계산량 대비 필요한 정보를 얻을지 검토합니다.","원지형 해상도, 배경 격자 병합과 Patch 경계의 일관성을 확인합니다. Patch의 세밀함은 배경과 비교한 것이며 원자료 이상의 지형정보를 뜻하지 않습니다.","같은 원지형 격자에서 배경은 묶고 관심구간은 원해상도로 남기는 관계를 보세요.","Consider where retaining source-terrain resolution provides useful detail for the computational cost.","Check source resolution, background aggregation and patch interfaces. Patch detail is relative to the background, not finer terrain information than the source.","See background cells grouped from one source grid while selected areas retain source resolution.",["local-inertia","channelbed"]],
 "flood-extras":["범람 분석에 추가할 외력·구조물 작용과 이동경로 분석을 구분해 선택합니다.","사용할 구성요소의 지원·검증 범위를 각각 확인합니다. 모든 요소가 모든 설정에서 동일하게 지원된다고 가정하지 않습니다.","그림은 공통 범람원·격자 배경입니다. 강우·배수·추적자의 모든 구현이나 결과를 한 번에 나타내지는 않습니다.","Distinguish additional forcing and structure effects from transport-analysis layers.","Check support and validation for each selected component rather than assuming universal support across all configurations.","The shared picture shows the floodplain grid, not every extension or its outputs.",["structures","dye"]],
 "sed-hill":["유사가 발생하는 사면과 하류로 전달되는 기여를 구분해 살펴봅니다.","침식원·토양 조건과 운반능 가정을 확인하고 유사 관련 자료로 별도 평가합니다.","사면의 침식원에서 물을 따라 이동해 퇴적되는 순서를 보세요.","Distinguish sediment source areas on hillslopes from their downstream contributions.","Review sediment sources, soil conditions and transport-capacity assumptions against sediment-specific evidence.","Follow hillslope erosion, transport by flow and downstream deposition.",["sed-river","runoff"]],
 "sed-river":["하천으로 들어온 유사가 구간을 통과하거나 퇴적되는 양상을 검토합니다.","상류 유사 입력과 하도 조건·운반능을 확인합니다. 사면의 유사 생성량과 하천 이송량을 구분합니다.","공통 그림 중 하천 내 이송·퇴적 구간에 주목하세요. 사면 침식 부분은 상류 공급 맥락입니다.","Examine whether incoming sediment passes through a reach or is deposited.","Review upstream sediment supply, channel conditions and transport capacity, distinguishing sediment production from river transport.","Focus on channel transport and deposition; hillslope erosion provides supply context in the shared illustration.",["sed-hill","dwnet"]],
 "dye":["주입된 보존성 물질의 도달 시점과 농도곡선의 변화를 살펴봅니다.","주입질량·시점·유량과 질량보존을 확인합니다. 반응·분해가 포함된 일반 수질예측과 구분합니다.","주입 위치와 하류의 관측 위치를 보세요. 색상은 이동 개념이며 실제 농도 등급이 아닙니다.","Inspect arrival timing and the evolving concentration curve of an injected conservative tracer.","Review injected mass, timing, discharge and mass conservation; distinguish conservative transport from reactive water-quality prediction.","Identify injection and downstream observation locations; colors are not measured concentration classes.",["wq","flood-extras"]],
 "wq":["현재 배포본으로 수행할 수 있는 분석인지 먼저 확인합니다.","활성 수질 계산이나 결과출력을 기대하지 않도록 배포본의 기능 범위를 확인합니다. 보존성 추적자와도 구분합니다.","현재 사용 가능한 수질 결과로 오인할 수 있어 예시 결과 그림을 제공하지 않습니다.","Check whether the intended analysis is available in the current package.","Check the package scope; do not expect active water-quality calculations or outputs, or confuse them with conservative tracers.","No example result is shown because it could imply an available water-quality calculation.",["dye","estuary"]],
 "parallel":["사용할 계산 자원에서 결과정합성을 유지하면서 실행시간을 줄일 수 있는지 비교합니다.","같은 입력에서 결과정합성과 실행시간을 함께 비교합니다. 코어 수 증가만으로 같은 비율의 속도 향상을 기대하지 않습니다.","작업을 나누고 결과를 모으는 구조를 보세요. 그림은 실제 성능 측정이나 속도 향상 수치가 아닙니다.","Compare whether available resources reduce runtime while preserving result consistency.","Compare result consistency and elapsed time for the same inputs; additional cores need not yield proportional speedup.","Read task partitioning and combination; the image is not a performance benchmark.",["output-integrity","netcdf"]],
 "netcdf":["서로 다른 결과 파일을 같은 위치·시점에서 비교할 수 있는지 판단합니다.","결과 분석 도구가 요구하는 변수 이름·차원·단위를 파일에 기록된 항목과 대조합니다.","계산 엔진의 결과가 파일을 거쳐 분석 도구로 전달되는 부분을 보세요.","Determine whether results from different files can be compared at matching locations and times.","Match the variable names, dimensions and units required by the analysis tool to those recorded in each file.","Follow the engine-to-output-file-to-analysis-tool connection.",["output-integrity","viewer"]],
 "viewer":["관심 위치의 침수 변화가 주변 공간분포와 어떻게 연결되는지 살펴봅니다.","비교 화면의 실제 시각·좌표·표시 단위를 확인하고 같은 범례 범위에서 공간분포를 읽습니다.","프로그램 관계도에서 결과를 받아 분석하는 끝단에 주목하세요. 실제 FloodViewer 화면은 아닙니다.","Relate changes at a location of interest to the surrounding spatial pattern.","Check actual timestamps, coordinates and displayed units; read spatial comparisons with consistent legend ranges.","Focus on the analysis end of the workflow; this is not a FloodViewer screenshot.",["netcdf","river-viewer"]],
 "inputstudio":["흩어진 원자료와 모의조건을 재검토할 수 있는 프로젝트로 준비합니다.","엔진 입력 파일을 기준으로 필수자료의 누락과 원자료 변경에 따른 불일치를 확인합니다.","자료 작성·검사가 계산 엔진보다 앞에 놓이는 흐름을 보세요. 실제 편집 화면은 아닙니다.","Prepare scattered source data and simulation settings as a reviewable project.","Review engine input files for missing required data and inconsistencies introduced by source-data changes.","Focus on preparation and checking before the engine; the image is not an editor screenshot.",["input-precheck","viewer"]],
 "estuary":["하천 유입과 해수 경계가 하구의 연직 염분 분포에 미치는 영향을 연구합니다.","상류 유입·조위·염분 자료의 기준시각과 경계조건을 맞추고 성층 변화를 관측자료와 비교합니다.","하천수와 해수의 연직 분포를 x-z 단면에서 보세요. 평면 범람지도와 다른 단면입니다.","Study how river inflow and marine boundaries affect vertical salinity structure.","Align upstream inflow, tidal and salinity time references and boundary conditions, and compare stratification with observations.","Read the vertical freshwater–seawater distribution in an x-z section, not a plan-view flood map.",["dye","dwnet"]],
 "river-viewer":["수위 변화가 어느 하천 구간·단면·시점에서 나타나는지 연결해 읽습니다.","현재 미공개 상태와 결과파일 호환성을 확인합니다. 계산 엔진과 뷰어는 별도 역할입니다.","종단면은 하천을 따른 변화, 횡단면은 단면 형상, 시계열은 시간 변화를 설명합니다. 실제 화면은 아닙니다.","Connect a water-level change to its river reach, cross section and time.","Check its unpublished status and result-file compatibility; the solver and viewer serve different roles.","Profiles show along-river change, cross sections show geometry, and time series show temporal change; these are not screenshots.",["dwnet","viewer"]]
};
function get(id,lang){const row=rows[id];if(!row)throw Error('Missing user guidance: '+id);const offset=lang==='ko'?0:3;return {goal:row[offset],check:row[offset+1],figure:row[offset+2],related:row[6]};}
function validate(data){const assert=require('node:assert/strict');assert.equal(Object.keys(rows).length,data.items.length);for(const item of data.items){const row=rows[item.id];assert.equal(row?.length,7,item.id);for(const value of row.slice(0,6))assert.ok(typeof value==='string'&&value.trim(),item.id);assert.ok(row[6].length>=1&&row[6].every(id=>id!==item.id&&data.items.some(i=>i.id===id)),item.id+' related');}}
module.exports={rows,get,validate};
